using BrewNest.Contracts.Returns;using BrewNest.Modules.Inventory.Domain.Entities;using BrewNest.Modules.Inventory.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;
namespace BrewNest.Modules.Inventory.Application.Interfaces;
internal sealed class ReturnsInventoryPort(InventoryDbContext database,TimeProvider clock):IReturnsInventoryPort
{
 public async Task<ReturnsPortResult> RestockAsync(string reference,ReturnsInventoryRestock item,string actor,CancellationToken t){if(item.Quantity<=0||item.ExpiryDate<=DateOnly.FromDateTime(clock.GetUtcNow().UtcDateTime)||string.IsNullOrWhiteSpace(item.LotNumber))return new(false,["Restock lot, quantity, and expiry are invalid."]);var lot=await database.StockLots.SingleOrDefaultAsync(x=>x.ItemId==item.ItemId&&x.WarehouseId==item.WarehouseId&&x.LotNumber==item.LotNumber,t);if(lot is null){lot=new(){Id=Guid.NewGuid(),ItemId=item.ItemId,WarehouseId=item.WarehouseId,LotNumber=item.LotNumber,ManufacturingDate=item.ManufacturingDate,ExpiryDate=item.ExpiryDate,CreatedAt=clock.GetUtcNow(),CreatedBy=actor};database.StockLots.Add(lot);}if(lot.IsBlocked)return new(false,["The returned lot is blocked."]);lot.OnHandQuantity+=item.Quantity;lot.ModifiedAt=clock.GetUtcNow();lot.ModifiedBy=actor;database.Movements.Add(new(){Id=Guid.NewGuid(),StockLotId=lot.Id,ItemId=lot.ItemId,WarehouseId=lot.WarehouseId,MovementType=StockMovementType.GoodsReceipt,Quantity=item.Quantity,OnHandAfter=lot.OnHandQuantity,ReservedAfter=lot.ReservedQuantity,ReferenceType="CustomerReturn",ReferenceNumber=reference,Remarks="Approved returned-food restock.",PerformedBy=actor,PerformedAt=clock.GetUtcNow()});await database.SaveChangesAsync(t);return new(true,[]);}
 public Task<ReturnsPortResult> DisposeAsync(string reference,ReturnsInventoryDisposal item,string actor,CancellationToken t)=>Task.FromResult(item.Quantity>0?new ReturnsPortResult(true,[]):new ReturnsPortResult(false,["Disposal quantity must be positive."]));
}
